from admissions_records import *

def spring():
 c=cycle(L('Spring 2027 only; Fall rules not established','Только Spring 2027; осенние правила не установлены'),[2027]);c['intakes']=['spring-2027'];return c
sejong='https://www.sejong.ac.kr/_res/sejong/eng/etc/2027_Spring_Semester_Undergraduate_Admission_Guide_for_International_Students(eng)_20260903.pdf'
ss=[S(sejong,L('Sejong Spring 2027 undergraduate guide: eligibility and documents','Sejong: руководство бакалавриата Spring 2027, допуск и документы'),pages=[4,5,6,9,10,11,17],access='pdf-read')]
aa={'satPolicy':'unknown','note':L('The read eligibility and document sections do not establish an independent SAT/ACT policy. Recognised school completion remains compulsory.','Прочитанные разделы допуска и документов не устанавливают отдельную политику SAT/ACT. Признанное школьное образование остаётся обязательным.')}
docs=[L('Upload authenticated scans during application; admitted students who enrol must then send originals during registration. Online submission and receipt of originals are separate stages. Applicant and both parents must be non-Korean nationals; nationality-acquisition exclusions apply.','Загрузите заверенные сканы при подаче; зачисленные, решившие учиться, затем направляют оригиналы при регистрации. Онлайн-подача и получение оригиналов — разные этапы. Кандидат и оба родителя — не граждане Кореи; действуют ограничения по приобретению гражданства.')]
record('sejong-university',[
 route(id='english-track',label=L('Listed English-track bachelor majors, Seoul','Перечисленные англоязычные специальности бакалавриата, Сеул'),programmeIds=['business','economics','computer-science','social-sciences'],applicability=spring(),english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':5.5,'role':'admission'},'toefl':{'accepted':True,'scales':[{'period':'pre2026','min':59},{'period':'post2026','min':3.5}]},'alternatives':L('New TEPS 202. TOEFL Home Edition and MyBest accepted; ITP not accepted. Listed first-year tracks include Business, Economics, Computer Science and Engineering, Public Administration and other named majors; not every major is English.','New TEPS 202. TOEFL Home Edition и MyBest принимаются; ITP — нет. Среди указанных англоязычных маршрутов первокурсника: Business, Economics, Computer Science and Engineering, Public Administration и другие названные специальности; не все программы английские.'),'waiver':L('Citizenship of a country with native/official English plus proof of secondary/higher education may qualify. Non-English-country citizens must provide a test even after English-medium education abroad.','Может подойти гражданство страны с родным/официальным английским вместе с подтверждением среднего/высшего образования. Для граждан неанглоязычных стран тест обязателен даже после англоязычного обучения за рубежом.')},academic=aa,documents=docs,sources=ss),
 route(id='korean-track',label=L('Korean-track bachelor majors — programme-specific TOPIK','Корейскоязычный бакалавриат — TOPIK зависит от специальности'),language='ko',applicability=spring(),localLanguage=[{'name':'TOPIK','requirement':L('Level 4: Korean Language/Literature, Media/Communication and Business; level 3 for other ordinary majors. Creative/Arts/PE/Entertainment: level 2 with compulsory additional language study. Global Liberal Studies has no entry-language requirement.','Уровень 4: Korean Language/Literature, Media/Communication и Business; уровень 3 для остальных обычных специальностей. Creative/Arts/PE/Entertainment: уровень 2 с обязательным дополнительным языковым обучением. Global Liberal Studies не требует языка при входе.'),'note':L('Specified KIIP/King Sejong Institute equivalents and Sejong language-course completion may substitute. Graduation TOPIK requirements remain separate; Sejong Prep must be completed before regular admission.','Могут заменять указанные эквиваленты KIIP/King Sejong Institute и курс Sejong. Выпускные требования TOPIK отдельные; Sejong Prep нужно закончить до обычного зачисления.')}],academic=aa,documents=docs,sources=ss)
 ],'Separated Spring 2027 English 5.5 entry from major-specific Korean qualifications, limited nationality waiver and staged original documents.', ['Fall 2027 rules, IELTS variant/sections and independent SAT/ACT obligations remain unconfirmed.'])

pusan='https://international.pusan.ac.kr/bbs/international/2089/1533745/download.do'
ps=[S(pusan,L('Pusan Spring 2027 undergraduate guide: English section','Pusan: англоязычный раздел руководства бакалавриата Spring 2027'),pages=[32,33,34],access='pdf-read')]
exception=L('Nepalese, Mongolian, Vietnamese and Uzbek applicants: IELTS 7 or TOEFL iBT 85 (guide new scale 5) for Global Studies, and TOPIK 5 for Korean routes. The ordinary departmental minimum must not be applied to these categories.','Для граждан Непала, Монголии, Вьетнама и Узбекистана: IELTS 7 либо TOEFL iBT 85 (новая шкала руководства 5) для Global Studies и TOPIK 5 для корейских маршрутов. Обычный минимум подразделения нельзя применять к этим категориям.')
record('pusan-national-university',[
 route(id='global-studies',label=L('Department of Global Studies — English, Busan campus','Department of Global Studies — английский, кампус Busan'),programmeIds=['social-sciences'],applicability=spring(),english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':None},'toefl':{'accepted':True},'alternatives':L('Ordinary category: IELTS 5.5, TOEFL iBT 80 (guide new scale 4) or New TEPS 327. TOPIK is not compulsory for Global Studies. Nationality-specific higher thresholds prevent one universal numerical minimum.','Обычная категория: IELTS 5,5, TOEFL iBT 80 (новая шкала руководства 4) либо New TEPS 327. Для Global Studies TOPIK необязателен. Повышенные пороги по гражданству не позволяют задать один универсальный числовой минимум.'),'note':exception,'waiver':L('The guide lists US, UK, Australia, Canada, Ireland, New Zealand and South Africa; confirm the required school-history evidence with admissions.','Руководство перечисляет США, Великобританию, Австралию, Канаду, Ирландию, Новую Зеландию и ЮАР; требуемое подтверждение школьного обучения уточняется у приёмной комиссии.')},academic={'satPolicy':'unknown'},sources=ps),
 route(id='korean-ai-computing',label=L('AI Computer Science and Engineering — Korean, Busan campus','AI Computer Science and Engineering — корейский, кампус Busan'),language='ko',programmeIds=['computer-science'],applicability=spring(),localLanguage=[{'name':'TOPIK','requirement':L('Normally level 4 or PNU language level 4. With the specified English evidence, level 3/PNU level 3 may qualify; these majors are explicitly NOT English tracks.','Обычно уровень 4 либо языковой курс PNU уровня 4. С указанным подтверждением английского возможен уровень 3/PNU 3; эти специальности прямо НЕ названы английскими маршрутами.'),'note':exception}],academic={'satPolicy':'unknown'},sources=ps)
 ],'Removed an unqualified English threshold and distinguished the only wholly English department from Korean computing and nationality exceptions.', ['Fall intake is not established: the guide states undergraduate curricula follow March entry. IELTS variant/sections, SAT/ACT policy and additional nationality-specific financial documents require further review.'])
finish()
